#!/usr/bin/env python3
"""Compile token-path policies to canonical minimal deterministic automata."""

import json
import sys
from collections import deque

MAX_LINE = 1_048_576
MAX_DEPTH = 64
MAX_PRODUCT_STATES = 20_000


class DuplicateKey(ValueError):
    pass


def _object_without_duplicates(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise DuplicateKey(key)
        result[key] = value
    return result


def _forbidden_constant(_value):
    raise ValueError("non-JSON numeric constant")


def _depth_limit_exceeded(text):
    """Perform the contract's deliberately type-insensitive preliminary scan."""
    depth = 0
    in_string = False
    escaped = False
    for char in text:
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
        else:
            if char == '"':
                in_string = True
            elif char == "{" or char == "[":
                depth += 1
                if depth > MAX_DEPTH:
                    return True
            elif char == "}" or char == "]":
                if depth:
                    depth -= 1
    return False


def _strings_are_scalars(value):
    """JSON decoding can leave lone surrogates; reject them at schema stage."""
    if isinstance(value, str):
        return not any(0xD800 <= ord(char) <= 0xDFFF for char in value)
    if isinstance(value, list):
        return all(_strings_are_scalars(item) for item in value)
    if isinstance(value, dict):
        for key, item in value.items():
            if not _strings_are_scalars(key) or not _strings_are_scalars(item):
                return False
        return True
    return True


class SchemaError(Exception):
    pass


class LimitError(Exception):
    pass


_ATOM_OPS = {"match", "startswith", "endswith", "contains"}


def _validate_and_normalize(request):
    """Check all schema conditions, then all declared size conditions."""
    if not isinstance(request, dict) or set(request) != {"services", "rules", "queries"}:
        raise SchemaError()
    if not _strings_are_scalars(request):
        raise SchemaError()

    services = request["services"]
    rules = request["rules"]
    queries = request["queries"]
    if not isinstance(services, list) or not isinstance(rules, list) or not isinstance(queries, list):
        raise SchemaError()

    service_ids = {}
    for token in services:
        if not isinstance(token, str) or not token or token in service_ids:
            raise SchemaError()
        service_ids[token] = len(service_ids)

    def convert_path(path):
        if not isinstance(path, list):
            raise SchemaError()
        converted = []
        for token in path:
            if not isinstance(token, str) or token not in service_ids:
                raise SchemaError()
            converted.append(service_ids[token])
        return converted

    atom_ids = {}
    atoms = []
    node_count = 0
    argument_counts = []
    atomic_path_lengths = []

    def expression(value):
        nonlocal node_count
        if not isinstance(value, dict) or "op" not in value or not isinstance(value["op"], str):
            raise SchemaError()
        node_count += 1
        op = value["op"]
        if op == "true" or op == "false":
            if set(value) != {"op"}:
                raise SchemaError()
            return (op,)
        if op in _ATOM_OPS:
            if set(value) != {"op", "path"}:
                raise SchemaError()
            path = convert_path(value["path"])
            atomic_path_lengths.append(len(path))
            identity = (op, tuple(path))
            atom_id = atom_ids.get(identity)
            if atom_id is None:
                atom_id = len(atoms)
                atom_ids[identity] = atom_id
                atoms.append((op, tuple(path)))
            return ("atom", atom_id)
        if op == "not":
            if set(value) != {"op", "arg"}:
                raise SchemaError()
            return ("not", expression(value["arg"]))
        if op == "and" or op == "or":
            if set(value) != {"op", "args"} or not isinstance(value["args"], list):
                raise SchemaError()
            argument_counts.append(len(value["args"]))
            children = tuple(expression(child) for child in value["args"])
            return (op, children)
        raise SchemaError()

    normalized_rules = []
    for rule in rules:
        if not isinstance(rule, dict) or set(rule) != {"action", "when"}:
            raise SchemaError()
        action = rule["action"]
        if action != "allow" and action != "drop":
            raise SchemaError()
        normalized_rules.append((action, expression(rule["when"])))

    normalized_queries = []
    query_token_count = 0
    query_lengths = []
    for path in queries:
        converted = convert_path(path)
        query_lengths.append(len(converted))
        query_token_count += len(converted)
        normalized_queries.append(converted)

    # No size error is raised until the complete schema has been checked.
    if len(services) > 24 or any(len(token) > 64 for token in services):
        raise LimitError()
    if len(rules) > 32 or node_count > 256:
        raise LimitError()
    if any(count > 32 for count in argument_counts):
        raise LimitError()
    if any(length > 16 for length in atomic_path_lengths):
        raise LimitError()
    if len(atoms) > 10:
        raise LimitError()
    if len(queries) > 256 or query_token_count > 16_384:
        raise LimitError()
    if any(length > 4_096 for length in query_lengths):
        raise LimitError()

    return services, normalized_rules, normalized_queries, atoms


class Monitor:
    __slots__ = ("transitions", "accepting")

    def __init__(self, op, pattern, alphabet_size):
        m = len(pattern)
        accepting = [False] * (m + 1)
        accepting[m] = True

        if op == "match":
            # The extra failure state is m+1.
            transitions = [[m + 1] * alphabet_size for _ in range(m + 2)]
            for k in range(m):
                for token in range(alphabet_size):
                    if token == pattern[k]:
                        transitions[k][token] = k + 1
            accepting.append(False)
        elif op == "startswith":
            transitions = [[m + 1] * alphabet_size for _ in range(m + 2)]
            for k in range(m):
                for token in range(alphabet_size):
                    if token == pattern[k]:
                        transitions[k][token] = k + 1
            transitions[m] = [m] * alphabet_size
            accepting.append(False)
        else:
            transitions = [[0] * alphabet_size for _ in range(m + 1)]
            if op == "contains":
                # The accepting occurrence state is absorbing.  For m=0 this
                # also gives the required single true looping state.
                transitions[m] = [m] * alphabet_size
                for k in range(m):
                    self._prefix_suffix_row(transitions, k, pattern, alphabet_size)
            else:
                # For endswith, the largest state is not absorbing: its next
                # state is computed from p + [a], just like every other state.
                for k in range(m + 1):
                    self._prefix_suffix_row(transitions, k, pattern, alphabet_size)

        self.transitions = transitions
        self.accepting = accepting

    @staticmethod
    def _prefix_suffix_row(transitions, k, pattern, alphabet_size):
        # m <= 16, so directly implementing the defining largest-j rule is
        # both small and less error-prone than a special-cased KMP variant.
        m = len(pattern)
        prefix = pattern[:k]
        for token in range(alphabet_size):
            sequence = prefix + (token,)
            largest = 0
            for j in range(1, m + 1):
                if j <= len(sequence) and sequence[-j:] == pattern[:j]:
                    largest = j
            transitions[k][token] = largest


def _product_monitor(atoms, alphabet_size):
    """Return the exact reachable synchronous product, or None over the cap."""
    monitors = [Monitor(op, pattern, alphabet_size) for op, pattern in atoms]
    initial = tuple(0 for _ in monitors)
    state_ids = {initial: 0}
    states = [initial]
    transitions = []
    cursor = 0
    while cursor < len(states):
        state = states[cursor]
        row = []
        for token in range(alphabet_size):
            successor = tuple(monitor.transitions[k][token]
                              for monitor, k in zip(monitors, state))
            state_id = state_ids.get(successor)
            if state_id is None:
                state_id = len(states)
                if state_id >= MAX_PRODUCT_STATES:
                    return None
                state_ids[successor] = state_id
                states.append(successor)
            row.append(state_id)
        transitions.append(row)
        cursor += 1
    return states, transitions, monitors


def _evaluate(expression, atom_values):
    op = expression[0]
    if op == "atom":
        return atom_values[expression[1]]
    if op == "true":
        return True
    if op == "false":
        return False
    if op == "not":
        return not _evaluate(expression[1], atom_values)
    if op == "and":
        for child in expression[1]:
            if not _evaluate(child, atom_values):
                return False
        return True
    # or; an empty argument list naturally returns False.
    for child in expression[1]:
        if _evaluate(child, atom_values):
            return True
    return False


def _acceptance_vector(states, rules, monitors):
    allows = [expression for action, expression in rules if action == "allow"]
    drops = [expression for action, expression in rules if action == "drop"]
    result = []
    for state in states:
        values = tuple(monitor.accepting[k] for monitor, k in zip(monitors, state))
        allowed = False
        for expression in allows:
            if _evaluate(expression, values):
                allowed = True
                break
        if allowed:
            for expression in drops:
                if _evaluate(expression, values):
                    allowed = False
                    break
        result.append(allowed)
    return result


def _minimize(transitions, accepting):
    """Hopcroft partition refinement on a reachable, complete DFA."""
    n = len(transitions)
    alphabet_size = len(transitions[0])

    # Reverse transitions make each splitter inexpensive even for long chains.
    predecessors = [[[] for _ in range(n)] for _ in range(alphabet_size)]
    for source, row in enumerate(transitions):
        for token, target in enumerate(row):
            predecessors[token][target].append(source)

    blocks = {}
    state_block = [0] * n
    accepting_block = {state for state in range(n) if accepting[state]}
    rejecting_block = {state for state in range(n) if not accepting[state]}
    next_block = 0
    if accepting_block:
        blocks[next_block] = accepting_block
        for state in accepting_block:
            state_block[state] = next_block
        next_block += 1
    if rejecting_block:
        blocks[next_block] = rejecting_block
        for state in rejecting_block:
            state_block[state] = next_block
        next_block += 1
    work = set(blocks)

    while work:
        splitter_id = work.pop()
        # Keep this original object even if the splitter's own partition block
        # is replaced while processing one of the alphabet symbols.
        splitter = blocks[splitter_id]
        for token in range(alphabet_size):
            touched = {}
            token_predecessors = predecessors[token]
            for target in splitter:
                for source in token_predecessors[target]:
                    block_id = state_block[source]
                    intersection = touched.get(block_id)
                    if intersection is None:
                        touched[block_id] = [source]
                    else:
                        intersection.append(source)

            for block_id, intersection in touched.items():
                block = blocks[block_id]
                if len(intersection) == len(block):
                    continue
                inside = set(intersection)
                # If this is the active splitter, preserve its original value
                # for the remaining alphabet symbols before mutating the set.
                if block is splitter:
                    splitter = block.copy()
                block.difference_update(inside)
                new_id = next_block
                next_block += 1
                # The old block id denotes the difference, so only states in
                # the extracted intersection need their labels changed.
                blocks[new_id] = inside
                for state in inside:
                    state_block[state] = new_id

                if block_id in work:
                    work.add(new_id)
                elif len(inside) <= len(block):
                    work.add(new_id)
                else:
                    work.add(block_id)

    # Quotient transitions use representatives.  BFS then assigns the required
    # canonical labels independently of the partition refinement's set order.
    start_block = state_block[0]
    canonical = {start_block: 0}
    order = [start_block]
    minimal_transitions = []
    cursor = 0
    while cursor < len(order):
        block_id = order[cursor]
        representative = next(iter(blocks[block_id]))
        row = []
        for target in transitions[representative]:
            target_block = state_block[target]
            label = canonical.get(target_block)
            if label is None:
                label = len(order)
                canonical[target_block] = label
                order.append(target_block)
            row.append(label)
        minimal_transitions.append(row)
        cursor += 1

    minimal_accepting = [accepting[next(iter(blocks[block_id]))] for block_id in order]
    return minimal_transitions, minimal_accepting


def _distances(transitions, accepting):
    n = len(transitions)
    reverse = [[] for _ in range(n)]
    for source, row in enumerate(transitions):
        for target in row:
            reverse[target].append(source)

    distance = [None] * n
    queue = deque()
    for state, is_accepting in enumerate(accepting):
        if is_accepting:
            distance[state] = 0
            queue.append(state)
    while queue:
        target = queue.popleft()
        next_distance = distance[target] + 1
        for source in reverse[target]:
            if distance[source] is None:
                distance[source] = next_distance
                queue.append(source)
    return distance


def compile_bundle(request):
    services, rules, queries, atoms = _validate_and_normalize(request)
    product = _product_monitor(atoms, len(services))
    if product is None:
        return {"ok": False, "error": "E_COMPLEXITY"}
    states, transitions, monitors = product
    accepting = _acceptance_vector(states, rules, monitors)
    transitions, accepting = _minimize(transitions, accepting)
    distance = _distances(transitions, accepting)

    query_results = []
    for path in queries:
        state = 0
        for token in path:
            state = transitions[state][token]
        query_results.append({"state": state, "allow": accepting[state], "distance": distance[state]})

    return {
        "ok": True,
        "dfa": {
            "start": 0,
            "accept": accepting,
            "next": transitions,
            "distance": distance,
        },
        "queries": query_results,
    }


def _error(code):
    return {"ok": False, "error": code}


def _process_line(raw):
    if len(raw) > MAX_LINE:
        return _error("E_LIMIT")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return _error("E_JSON")
    if _depth_limit_exceeded(text):
        return _error("E_LIMIT")
    try:
        request = json.loads(text, object_pairs_hook=_object_without_duplicates,
                             parse_constant=_forbidden_constant)
    except (ValueError, RecursionError):
        return _error("E_JSON")
    try:
        return compile_bundle(request)
    except SchemaError:
        return _error("E_SCHEMA")
    except LimitError:
        return _error("E_LIMIT")


def main():
    for physical_line in sys.stdin.buffer:
        if physical_line.endswith(b"\n"):
            physical_line = physical_line[:-1]
        result = _process_line(physical_line)
        sys.stdout.write(json.dumps(result, separators=(",", ":")) + "\n")
        sys.stdout.flush()


if __name__ == "__main__":
    main()
